/* Nikoleta Wellness CEO — Learning Center. Local-first MVP; no cloud or paid API. */
const DB='NikoletaLearningCenter',VER=1,STORE='records';
let db,recorder=null,stream=null,recordParts=[],recordStarted=0,elapsedBefore=0,timerHandle=null,currentId=null;
let dbReady=null;
function ensureDB(){if(db)return Promise.resolve(db);if(!dbReady)dbReady=openDB().catch(error=>{dbReady=null;throw error});return dbReady}
const $=id=>document.getElementById(id);
const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const fmtDate=s=>new Date(s).toLocaleString('el-GR',{dateStyle:'medium',timeStyle:'short'});
const fmtTime=s=>{s=Math.floor(s||0);return [Math.floor(s/3600),Math.floor(s%3600/60),s%60].map(n=>String(n).padStart(2,'0')).join(':')};
function openDB(){return new Promise((resolve,reject)=>{const q=indexedDB.open(DB,VER);q.onupgradeneeded=()=>{const d=q.result;if(!d.objectStoreNames.contains(STORE))d.createObjectStore(STORE,{keyPath:'id'})};q.onsuccess=()=>{db=q.result;resolve(db)};q.onerror=()=>reject(q.error)})}
async function all(){await ensureDB();return new Promise((resolve,reject)=>{const q=db.transaction(STORE).objectStore(STORE).getAll();q.onsuccess=()=>resolve(q.result||[]);q.onerror=()=>reject(q.error)})}
async function put(v){await ensureDB();return new Promise((resolve,reject)=>{const tx=db.transaction(STORE,'readwrite');tx.objectStore(STORE).put(v);tx.oncomplete=resolve;tx.onerror=()=>reject(tx.error)})}
async function del(id){await ensureDB();return new Promise((resolve,reject)=>{const tx=db.transaction(STORE,'readwrite');tx.objectStore(STORE).delete(id);tx.oncomplete=resolve;tx.onerror=()=>reject(tx.error)})}
async function clearRecords(){await ensureDB();return new Promise((resolve,reject)=>{const tx=db.transaction(STORE,'readwrite');tx.objectStore(STORE).clear();tx.oncomplete=resolve;tx.onerror=()=>reject(tx.error)})}
async function replaceAll(records){await ensureDB();return new Promise((resolve,reject)=>{const tx=db.transaction(STORE,'readwrite'),store=tx.objectStore(STORE);store.clear();records.forEach(v=>store.put(v));tx.oncomplete=resolve;tx.onerror=()=>reject(tx.error);tx.onabort=()=>reject(tx.error||new Error('Η επαναφορά ακυρώθηκε'))})}
function download(blob,name){const a=document.createElement('a'),url=URL.createObjectURL(blob);a.href=url;a.download=name;document.body.append(a);a.click();a.remove();setTimeout(()=>URL.revokeObjectURL(url),30000)}
function showHome(){ $('home').classList.remove('hidden');$('view').classList.add('hidden');renderRecent();currentId=null}
function showView(html){$('home').classList.add('hidden');$('view').classList.remove('hidden');$('view').innerHTML=html;window.scrollTo(0,0)}
async function runGlobalSearch(term){const box=$('searchResults');if(!box)return;const q=term.trim().toLocaleLowerCase('el');if(!q){box.textContent='Γράψε μια λέξη για να βρεις τις αποθηκευμένες καταχωρίσεις σου.';return}const rows=await all();const hits=[];for(const x of rows){const fields=[x.title,x.speaker,x.description,x.body,x.transcript,x.notes,x.summary,x.learning,x.personal];const match=fields.some(v=>String(v||'').toLocaleLowerCase('el').includes(q));if(match)hits.push(x)}box.innerHTML=hits.length?hits.slice(0,15).map(x=>'<div class="fileitem"><div><strong>'+esc(x.title||'Χωρίς τίτλο')+'</strong><div class="note">'+esc(x.type==='seminar'?'Σεμινάριο':(simple[x.type?.replace('module_','')]||['Καταχώριση'])[0])+' · '+fmtDate(x.updated||x.created)+'</div></div><button class="btn light" data-search-open="'+x.id+'">Άνοιγμα</button></div>').join(''):'Δεν βρέθηκαν αποτελέσματα.';document.querySelectorAll('[data-search-open]').forEach(b=>b.onclick=async()=>{const x=(await all()).find(v=>v.id===b.dataset.searchOpen);if(x?.type==='seminar')openSeminar(x.id);else if(x){const k=x.type.replace('module_','');simpleView(k)}})}
async function renderRecent(){const items=(await all()).filter(x=>x.type==='seminar').sort((a,b)=>b.updated-a.updated);$('seminarCount').textContent=items.length+' σεμινάρια';$('recentList').innerHTML=items.length?items.slice(0,5).map(s=>seminarCard(s)).join(''):'<p class="muted">Δεν έχεις δημιουργήσει ακόμη σεμινάριο.</p>';bindSeminarCards()}
function seminarCard(s){const n=(s.audio||[]).filter(a=>a.kind!=='recording-part').length,done=[s.transcript,s.notes,s.summary,s.learning].filter(v=>String(v||'').trim()).length;return '<article class="seminar seminar-card"><div class="seminar-card-main"><span class="seminar-date">'+fmtDate(s.created)+'</span><strong>'+esc(s.title)+'</strong><small>'+(s.speaker?'🎤 '+esc(s.speaker)+' · ':'')+n+' αρχεία ήχου · '+done+'/4 ενότητες</small><div class="seminar-progress"><span style="width:'+(done*25)+'%"></span></div></div><div class="seminar-card-actions"><span class="pill">'+esc(s.status||'Σε εξέλιξη')+'</span><button class="btn light" data-seminar="'+s.id+'">Άνοιγμα φακέλου →</button></div></article>'}
function bindSeminarCards(){document.querySelectorAll('[data-seminar]').forEach(b=>b.onclick=()=>openSeminar(b.dataset.seminar))}
async function audioDashboard(){const items=(await all()).filter(x=>x.type==='seminar').sort((a,b)=>b.updated-a.updated),audio=items.reduce((n,s)=>n+(s.audio||[]).filter(a=>a.kind!=='recording-part').length,0),done=items.filter(s=>s.status==='Ολοκληρώθηκε').length;showView('<div class="audio-hero"><div class="audio-hero-copy"><span class="audio-eyebrow">NIKOΛΕΤΑ WELLNESS CEO · LEARNING LIBRARY</span><h2>Σεμινάρια & Ηχογραφήσεις</h2><p>Ο προσωπικός σου χώρος για κάθε εκπαίδευση: ηχογραφήσεις, πλήρη κείμενα, σημειώσεις και υλικό μελέτης — όλα οργανωμένα σε ξεχωριστούς φακέλους.</p><div class="audio-hero-actions"><button class="btn gold" id="createAudioSem">＋ Δημιουργία σεμιναρίου</button><button class="btn light" id="audioBackup">Αντίγραφο ασφαλείας</button></div></div><div class="audio-hero-mark">✧<small>AUDIO<br>ACADEMY</small></div></div><div class="audio-stats"><div class="audio-stat"><span>ΣΥΝΟΛΙΚΑ ΣΕΜΙΝΑΡΙΑ</span><strong>'+items.length+'</strong></div><div class="audio-stat"><span>ΑΡΧΕΙΑ ΗΧΟΥ</span><strong>'+audio+'</strong></div><div class="audio-stat"><span>ΟΛΟΚΛΗΡΩΜΕΝΑ</span><strong>'+done+'</strong></div></div><div class="audio-toolbar"><div class="field"><label for="seminarSearch">Αναζήτηση στους φακέλους</label><input id="seminarSearch" type="search" placeholder="Τίτλος, εισηγητής ή θεματική..."></div><div class="field"><label for="seminarFilter">Προβολή</label><select id="seminarFilter"><option value="all">Όλα τα σεμινάρια</option><option value="active">Σε εξέλιξη</option><option value="done">Ολοκληρωμένα</option><option value="audio">Με ηχογράφηση</option><option value="text">Με απομαγνητοφώνηση</option></select></div></div><div class="audio-section-heading"><div><span class="audio-eyebrow">Η ΠΡΟΣΩΠΙΚΗ ΣΟΥ ΣΥΛΛΟΓΗ</span><h3>Οι φάκελοί μου</h3></div><span class="muted" id="seminarResultCount">'+items.length+' φάκελοι</span></div><div class="audio-folder-list" id="seminarFolderList">'+(items.length?items.map(s=>seminarCard(s)).join(''):'<div class="audio-empty"><div>🎙️</div><h3>Η συλλογή σου ξεκινά εδώ</h3><p>Δημιούργησε τον πρώτο σου φάκελο για να κρατήσεις συγκεντρωμένα την εκπαίδευση, τον ήχο και τις σημειώσεις σου.</p><button class="btn gold" id="emptyCreate">＋ Δημιουργία πρώτου φακέλου</button></div>')+'</div><div class="audio-footnote"><strong>🔒 Ιδιωτικότητα & αποθήκευση</strong><p>Οι ηχογραφήσεις και τα κείμενα αποθηκεύονται τοπικά σε αυτή τη συσκευή. Δεν απαιτείται συνδρομή ή πληρωμένη υπηρεσία. Χρησιμοποίησε τα αντίγραφα ασφαλείας για μεταφορά σε άλλη συσκευή.</p></div>');$('createAudioSem').onclick=newSeminar;$('audioBackup').onclick=backup;$('emptyCreate')?.addEventListener('click',newSeminar);bindSeminarCards();const filter=()=>{const q=$('seminarSearch').value.trim().toLocaleLowerCase('el'),f=$('seminarFilter').value,shown=items.filter(s=>[s.title,s.speaker,s.description,s.category].some(v=>String(v||'').toLocaleLowerCase('el').includes(q))&&(f==='all'||(f==='active'&&s.status!=='Ολοκληρώθηκε')||(f==='done'&&s.status==='Ολοκληρώθηκε')||(f==='audio'&&(s.audio||[]).some(a=>a.kind!=='recording-part'))||(f==='text'&&!!String(s.transcript||'').trim())));$('seminarFolderList').innerHTML=shown.length?shown.map(s=>seminarCard(s)).join(''):'<div class="audio-empty"><h3>Δεν βρέθηκαν φάκελοι</h3><p>Δοκίμασε διαφορετική αναζήτηση ή φίλτρο.</p></div>';$('seminarResultCount').textContent=shown.length+' φάκελοι';bindSeminarCards()};$('seminarSearch').oninput=filter;$('seminarFilter').onchange=filter}
function newSeminar(){showView('<div class="hero"><div><span class="audio-eyebrow">AUDIO ACADEMY · ΝΕΟΣ ΦΑΚΕΛΟΣ</span><h2>Δημιουργία νέου σεμιναρίου</h2><p>Κάθε εκπαίδευση αποκτά τον δικό της οργανωμένο χώρο.</p></div><button class="btn light" id="back">← Σεμινάρια</button></div><div class="panel seminar-create-panel"><div class="field"><label for="semTitle">Τίτλος σεμιναρίου *</label><input id="semTitle" placeholder="π.χ. Η Δύναμη της Επικοινωνίας"></div><div class="field"><label for="semSpeaker">Εισηγητής / Διοργανωτής</label><input id="semSpeaker" placeholder="Όνομα εισηγητή ή φορέα"></div><div class="field"><label for="semCategory">Κατηγορία εκπαίδευσης</label><select id="semCategory"><option>Επικοινωνία & NLP</option><option>Ηγεσία & Επιχειρηματικότητα</option><option>Herbalife Nutrition</option><option>Προσωπική ανάπτυξη</option><option>Marketing & Social Media</option><option>Άλλο</option></select></div><div class="field"><label for="semDate">Ημερομηνία σεμιναρίου</label><input id="semDate" type="date" value="'+new Date().toISOString().slice(0,10)+'"></div><div class="field"><label for="semDesc">Περιγραφή / βασικό αντικείμενο</label><textarea id="semDesc" placeholder="Τι θα διδαχθείς; Ποια θέματα θέλεις να κρατήσεις;"></textarea></div><p class="note">Ο φάκελος θα περιλαμβάνει χώρο για ηχογράφηση, ανέβασμα αρχείου, πλήρη απομαγνητοφώνηση, περίληψη, αναλυτικές σημειώσεις, εκπαιδευτικό υλικό και προσωπικές ενέργειες.</p><div class="actions"><button class="btn gold" id="createSem">Δημιουργία φακέλου</button><button class="btn light" id="cancelSem">Ακύρωση</button></div></div>');$('back').onclick=audioDashboard;$('cancelSem').onclick=audioDashboard;$('createSem').onclick=async()=>{const title=$('semTitle').value.trim();if(!title){alert('Συμπλήρωσε τον τίτλο του σεμιναρίου.');$('semTitle').focus();return}const now=Date.now(),s={id:crypto.randomUUID(),type:'seminar',title,speaker:$('semSpeaker').value.trim(),category:$('semCategory').value,date:$('semDate').value,description:$('semDesc').value.trim(),created:now,updated:now,status:'Σε εξέλιξη',audio:[],transcript:'',notes:'',summary:'',learning:'',personal:'',glossary:'',examples:'',exercises:''};await put(s);openSeminar(s.id)}}
async function openSeminar(id){const s=(await all()).find(x=>x.id===id);if(!s)return audioDashboard();currentId=id;const field=(k,l,p)=>editor(k,l,s[k]||'',p);showView('<div class="hero"><div><span class="pill">ΠΡΟΣΩΠΙΚΟΣ ΦΑΚΕΛΟΣ ΕΚΠΑΙΔΕΥΣΗΣ</span><h2>'+esc(s.title)+'</h2><p>'+(s.category?esc(s.category)+' · ':'')+(s.speaker?'🎤 '+esc(s.speaker)+' · ':'')+esc(s.date||fmtDate(s.created))+'</p></div><div class="actions"><button class="btn light" id="backHome">← Όλοι οι φάκελοι</button><button class="btn gold" id="exportSem">Εξαγωγή υλικού</button></div></div><div class="seminar-meta-strip"><span>📁 '+esc(s.status||'Σε εξέλιξη')+'</span><span>🎙️ '+(s.audio||[]).filter(a=>a.kind!=='recording-part').length+' αρχεία ήχου</span><span>📝 '+(s.transcript?'Απομαγνητοφώνηση διαθέσιμη':'Εκκρεμεί απομαγνητοφώνηση')+'</span></div><div class="tabs seminar-tabs"><button class="tab active" data-tab="audioTab">🎙️ Ηχογράφηση & αρχεία</button><button class="tab" data-tab="textTab">📝 Απομαγνητοφώνηση</button><button class="tab" data-tab="studyTab">🎓 Εκπαιδευτικό υλικό</button><button class="tab" data-tab="personalTab">✦ Προσωπική εφαρμογή</button></div><div id="audioTab"><div class="recbox seminar-record-box"><div class="recbox-heading"><div><span class="audio-eyebrow">LIVE AUDIO CAPTURE</span><h3>Ηχογράφηση σεμιναρίου</h3><p class="note">Η εγγραφή αποθηκεύεται τμηματικά στη συσκευή σου. Κράτησε ανοιχτή την εφαρμογή όσο ηχογραφείς.</p></div><div class="rec-mic">🎙️</div></div><div class="timer" id="timer">00:00:00</div><p class="note" id="recStatus">Έτοιμη για ηχογράφηση.</p><div class="actions"><button class="btn gold" id="startRec">● Έναρξη</button><button class="btn light" id="pauseRec" disabled>Ⅱ Παύση</button><button class="btn light" id="resumeRec" disabled>▶ Συνέχεια</button><button class="btn danger" id="stopRec" disabled>■ Ολοκλήρωση</button></div></div><div class="panel"><div class="sectionhead"><h3>Αρχεία ήχου</h3><span class="muted">MP3 · M4A · WAV · WEBM · OGG</span></div><p class="note">Ανέβασε μια υπάρχουσα ηχογράφηση ή κράτησε νέα μέσα από την εφαρμογή. Τα αρχεία παραμένουν στη συσκευή.</p><input type="file" id="audioUpload" accept="audio/*,.mp3,.m4a,.wav,.ogg,.webm"><div id="audioFiles">'+audioList(s)+'</div></div></div><div id="textTab" class="hidden"><div class="panel"><span class="audio-eyebrow">FULL TRANSCRIPT</span><h3>Πλήρης απομαγνητοφώνηση</h3><p class="note">Πρόσθεσε το πλήρες κείμενο της ομιλίας. Η εφαρμογή αποθηκεύει το κείμενο τοπικά· δεν πραγματοποιεί αυτόματη μεταγραφή ήχου.</p><div class="field"><textarea id="transcript" rows="18" placeholder="Επικόλλησε ή πληκτρολόγησε εδώ το πλήρες κείμενο...">'+esc(s.transcript)+'</textarea></div><button class="btn gold" id="saveTranscript">Αποθήκευση απομαγνητοφώνησης</button></div></div><div id="studyTab" class="hidden"><div class="panel"><span class="audio-eyebrow">LEARNING NOTES</span><h3>Μετατροπή της γνώσης σε πράξη</h3><p class="note">Οργάνωσε όσα έμαθες σε υλικό που θα μπορείς να μελετήσεις και να ξαναχρησιμοποιήσεις.</p>'+field('summary','Περίληψη σεμιναρίου','Τα σημαντικότερα σημεία...')+field('notes','Αναλυτικές σημειώσεις','Θεματικές ενότητες, βασικές έννοιες και σημαντικά σημεία...')+field('learning','Εκπαιδευτικό υλικό / οδηγός μελέτης','Δομημένα μαθήματα, βήματα εφαρμογής, πρακτικές τεχνικές...')+field('glossary','Λεξιλόγιο & βασικές έννοιες','Όροι, ορισμοί και επεξηγήσεις...')+field('examples','Παραδείγματα & μελέτες περίπτωσης','Παραδείγματα που αναφέρθηκαν ή δικά σου...')+field('exercises','Ασκήσεις & ερωτήσεις κατανόησης','Ερωτήσεις, ασκήσεις και ενδεικτικές απαντήσεις...')+'<button class="btn gold" id="saveStudy">Αποθήκευση εκπαιδευτικού υλικού</button></div></div><div id="personalTab" class="hidden"><div class="panel"><span class="audio-eyebrow">MY ACTION PLAN</span><h3>Η προσωπική μου εφαρμογή</h3>'+field('personal','Προσωπικές σημειώσεις & συμπεράσματα','Οι δικές μου σκέψεις, ιδέες και παρατηρήσεις...')+'<div class="field"><label for="seminarStatus">Κατάσταση φακέλου</label><select id="seminarStatus"><option '+(s.status==='Σε εξέλιξη'?'selected':'')+'>Σε εξέλιξη</option><option '+(s.status==='Για μελέτη'?'selected':'')+'>Για μελέτη</option><option '+(s.status==='Ολοκληρώθηκε'?'selected':'')+'>Ολοκληρώθηκε</option></select></div><button class="btn gold" id="savePersonal">Αποθήκευση προσωπικής εφαρμογής</button></div></div>');$('backHome').onclick=audioDashboard;$('exportSem').onclick=()=>exportSeminar(s.id);document.querySelectorAll('[data-tab]').forEach(b=>b.onclick=()=>{document.querySelectorAll('[data-tab]').forEach(x=>x.classList.toggle('active',x===b));['audioTab','textTab','studyTab','personalTab'].forEach(k=>$(k).classList.toggle('hidden',k!==b.dataset.tab))});bindAudioActions(s);$('audioUpload').onchange=e=>uploadAudio(id,e.target.files[0]);$('saveTranscript').onclick=async()=>{s.transcript=$('transcript').value;s.updated=Date.now();await put(s);alert('Η απομαγνητοφώνηση αποθηκεύτηκε.')};$('saveStudy').onclick=async()=>{['notes','summary','learning','glossary','examples','exercises'].forEach(k=>s[k]=$(k).value);s.updated=Date.now();await put(s);alert('Το εκπαιδευτικό υλικό αποθηκεύτηκε.')};$('savePersonal').onclick=async()=>{s.personal=$('personal').value;s.status=$('seminarStatus').value;s.updated=Date.now();await put(s);alert('Οι προσωπικές σημειώσεις αποθηκεύτηκαν.')};$('startRec').onclick=()=>startRecording(id);$('pauseRec').onclick=pauseRecording;$('resumeRec').onclick=resumeRecording;$('stopRec').onclick=stopRecording}
function editor(id,label,value,placeholder){return '<div class="field"><label>'+label+'</label><textarea id="'+id+'" placeholder="'+placeholder+'">'+esc(value)+'</textarea></div>'}
function audioList(s){return s.audio?.length?s.audio.map((a,i)=>'<div class="fileitem"><div><strong>'+esc(a.name)+'</strong><div class="note">'+(a.size/1048576).toFixed(1)+' MB · '+fmtDate(a.date)+'</div></div><div class="row"><button class="btn light" data-play="'+i+'">▶ Αναπαραγωγή</button><button class="btn light" data-download="'+i+'">↓ Λήψη</button></div></div>').join(''):'<p class="muted">Δεν υπάρχουν ακόμη αρχεία ήχου.</p>'}
function bindAudioActions(s){document.querySelectorAll('[data-play]').forEach(b=>b.onclick=()=>{const a=s.audio[+b.dataset.play],url=URL.createObjectURL(a.blob),w=window.open('','_blank');if(w)w.document.write('<title>Αναπαραγωγή ήχου</title><audio controls autoplay src="'+url+'" style="width:95%;margin:20px"></audio>')});document.querySelectorAll('[data-download]').forEach(b=>b.onclick=()=>{const a=s.audio[+b.dataset.download];download(a.blob,a.name)})}
async function refreshAudio(id){const s=(await all()).find(x=>x.id===id);$('audioFiles').innerHTML=audioList(s);bindAudioActions(s)}
async function uploadAudio(id,file){if(!file)return;const s=(await all()).find(x=>x.id===id);s.audio.push({id:crypto.randomUUID(),name:file.name,blob:file,size:file.size,date:Date.now(),kind:'upload'});s.updated=Date.now();await put(s);await refreshAudio(id);$('audioUpload').value=''}
async function startRecording(id){try{if(!navigator.mediaDevices?.getUserMedia||!window.MediaRecorder)throw Error('Το πρόγραμμα περιήγησης δεν υποστηρίζει ηχογράφηση.');stream=await navigator.mediaDevices.getUserMedia({audio:true});const mime=['audio/webm;codecs=opus','audio/webm','audio/mp4'].find(t=>MediaRecorder.isTypeSupported(t));recorder=new MediaRecorder(stream,mime?{mimeType:mime}:undefined);const rec=recorder,recMime=rec.mimeType,sessionId=crypto.randomUUID();recordStarted=Date.now();elapsedBefore=0;let lastChunkSave=Promise.resolve();rec.ondataavailable=e=>{if(!e.data?.size)return;lastChunkSave=lastChunkSave.then(async()=>{const s=(await all()).find(x=>x.id===id);s.audio.push({id:crypto.randomUUID(),sessionId,name:'Προσωρινό τμήμα '+(s.audio.filter(a=>a.sessionId===sessionId).length+1),blob:e.data,size:e.data.size,date:Date.now(),kind:'recording-part'});s.updated=Date.now();await put(s)})};rec.onerror=()=>{$('recStatus').textContent='Παρουσιάστηκε σφάλμα ηχογράφησης. Τα ήδη αποθηκευμένα προσωρινά τμήματα διατηρούνται.'};rec.onstop=async()=>{try{await lastChunkSave;const s=(await all()).find(x=>x.id===id);const parts=s.audio.filter(a=>a.sessionId===sessionId).sort((a,b)=>a.date-b.date);if(parts.length){const blob=new Blob(parts.map(a=>a.blob),{type:recMime||'audio/webm'});s.audio=s.audio.filter(a=>a.sessionId!==sessionId);const ext=recMime.includes('mp4')?'m4a':'webm';s.audio.push({id:crypto.randomUUID(),name:'Ηχογράφηση_'+new Date().toISOString().replace(/[:.]/g,'-')+'.'+ext,blob,size:blob.size,date:Date.now(),kind:'recording'});s.updated=Date.now();await put(s)}if($('audioFiles'))await refreshAudio(id);if($('recStatus'))$('recStatus').textContent='Η ηχογράφηση ολοκληρώθηκε και αποθηκεύτηκε ως ενιαίο αρχείο.'}catch(err){if($('recStatus'))$('recStatus').textContent='Δεν ολοκληρώθηκε η σύνθεση του αρχείου. Έλεγξε τα προσωρινά τμήματα και τον διαθέσιμο χώρο.'}};rec.start(60000);$('startRec').disabled=true;$('pauseRec').disabled=false;$('stopRec').disabled=false;$('recStatus').textContent='Ηχογράφηση σε εξέλιξη. Τα δεδομένα αποθηκεύονται προσωρινά ανά περίπου λεπτό και ενώνονται στο τέλος.';timerHandle=setInterval(()=>$('timer').textContent=fmtTime(elapsedBefore+(rec?.state==='recording'?(Date.now()-recordStarted)/1000:0)),500)}catch(e){alert('Δεν ξεκίνησε η ηχογράφηση: '+e.message+'\\nΈλεγξε την άδεια μικροφώνου και άνοιξε την εφαρμογή μέσω HTTPS.')}}
function pauseRecording(){if(recorder?.state==='recording'){elapsedBefore+=(Date.now()-recordStarted)/1000;recorder.pause();$('pauseRec').disabled=true;$('resumeRec').disabled=false;$('recStatus').textContent='Η ηχογράφηση είναι σε παύση.'}}
function resumeRecording(){if(recorder?.state==='paused'){recordStarted=Date.now();recorder.resume();$('pauseRec').disabled=false;$('resumeRec').disabled=true;$('recStatus').textContent='Ηχογράφηση σε εξέλιξη.'}}
function stopRecording(){if(!recorder)return;recorder.stop();stream?.getTracks().forEach(t=>t.stop());stream=null;recorder=null;clearInterval(timerHandle);$('startRec').disabled=false;$('pauseRec').disabled=true;$('resumeRec').disabled=true;$('stopRec').disabled=true;$('recStatus').textContent='Η ηχογράφηση ολοκληρώθηκε. Τα τμήματα αποθηκεύτηκαν στον φάκελο. Μπορείς να τα κατεβάσεις ξεχωριστά.'}
async function exportSeminar(id){const s=(await all()).find(x=>x.id===id);if(!s)return;const stamp=new Date(s.created||Date.now()).toLocaleString('el-GR');const text='ΣΕΜΙΝΑΡΙΟ: '+s.title+'\\nΕισηγητής: '+(s.speaker||'—')+'\\nΗμερομηνία: '+stamp+'\\n\\nΠΕΡΙΓΡΑΦΗ\\n'+(s.description||'—')+'\\n\\nΠΛΗΡΗΣ ΑΠΟΜΑΓΝΗΤΟΦΩΝΗΣΗ\\n'+(s.transcript||'Δεν έχει προστεθεί κείμενο.')+'\\n\\nΑΝΑΛΥΤΙΚΕΣ ΣΗΜΕΙΩΣΕΙΣ\\n'+(s.notes||'—')+'\\n\\nΠΕΡΙΛΗΨΗ\\n'+(s.summary||'—')+'\\n\\nΕΚΠΑΙΔΕΥΤΙΚΟ ΥΛΙΚΟ\\n'+(s.learning||'—')+'\\n\\nΠΡΟΣΩΠΙΚΕΣ ΣΗΜΕΙΩΣΕΙΣ\\n'+(s.personal||'—');const html='<!doctype html><html lang="el"><meta charset="utf-8"><title>'+esc(s.title)+'</title><style>body{font-family:Arial,sans-serif;max-width:850px;margin:40px auto;line-height:1.65;color:#17392c}h1{color:#0b5036;border-bottom:3px solid #c9a65b;padding-bottom:12px}h2{color:#176b49;margin-top:28px}pre{white-space:pre-wrap;font:inherit}</style><h1>'+esc(s.title)+'</h1><p><b>Εισηγητής:</b> '+esc(s.speaker||'—')+'<br><b>Ημερομηνία:</b> '+esc(stamp)+'</p>'+[['Περιγραφή',s.description],['Πλήρης απομαγνητοφώνηση',s.transcript],['Αναλυτικές σημειώσεις',s.notes],['Περίληψη',s.summary],['Εκπαιδευτικό υλικό',s.learning],['Λεξιλόγιο & βασικές έννοιες',s.glossary],['Παραδείγματα & μελέτες περίπτωσης',s.examples],['Ασκήσεις & ερωτήσεις κατανόησης',s.exercises],['Προσωπικές σημειώσεις',s.personal]].map(([h,v])=>'<h2>'+h+'</h2><pre>'+esc(v||'—')+'</pre>').join('')+'</html>';download(new Blob([html],{type:'application/msword;charset=utf-8'}),safe(s.title)+'_Εκπαιδευτικό_Υλικό.doc');download(new Blob([text],{type:'text/plain;charset=utf-8'}),safe(s.title)+'_Κείμενο.txt');const meta={...s,audio:s.audio.map(a=>({id:a.id,name:a.name,size:a.size,date:a.date,kind:a.kind}))};download(new Blob([JSON.stringify(meta,null,2)],{type:'application/json'}),safe(s.title)+'_δεδομένα.json');for(const a of s.audio)download(a.blob,safe(s.title)+'_'+a.name)}
function safe(s){return String(s||'seminar').normalize('NFD').replace(/[\u0300-\u036f]/g,'').replace(/[^a-zA-Z0-9_-]+/g,'_').slice(0,60)}
function blobToDataURL(blob){return new Promise((resolve,reject)=>{const r=new FileReader();r.onload=()=>resolve(r.result);r.onerror=()=>reject(r.error);r.readAsDataURL(blob)})}
function dataURLToBlob(data){const [head,body]=data.split(',');const mime=(head.match(/data:([^;]+)/)||[])[1]||'application/octet-stream';const raw=atob(body);const bytes=new Uint8Array(raw.length);for(let i=0;i<raw.length;i++)bytes[i]=raw.charCodeAt(i);return new Blob([bytes],{type:mime})}
async function backup(){try{const items=await all();const total=items.reduce((n,s)=>n+(s.audio||[]).reduce((m,a)=>m+(a.size||0),0),0);if(total>300*1024*1024&&!confirm('Τα αρχεία ήχου είναι περίπου '+(total/1048576).toFixed(0)+' MB. Η δημιουργία αντιγράφου μπορεί να χρειαστεί αρκετή μνήμη. Συνέχεια;'))return;const records=[];for(const s of items){const copy={...s,audio:[]};for(const a of (s.audio||[])){copy.audio.push({...a,blobData:a.blob?await blobToDataURL(a.blob):null,blob:undefined})}if(s.fileBlob){copy.fileBlobData=await blobToDataURL(s.fileBlob);copy.fileBlob=undefined}records.push(copy)}const pack={format:'nikoleta-learning-center',version:2,created:new Date().toISOString(),recordCount:records.length,audioBytes:total,records};download(new Blob([JSON.stringify(pack)],{type:'application/json'}),'Nikoleta_Learning_Center_FULL_Backup_'+new Date().toISOString().slice(0,10)+'.json');alert('Το πλήρες αντίγραφο δημιουργήθηκε. Περιλαμβάνει κείμενα, σημειώσεις και ηχογραφήσεις. Κράτησέ το σε δύο διαφορετικά σημεία.')}catch(e){alert('Δεν ολοκληρώθηκε το αντίγραφο: '+e.message+'\\nΔοκίμασε ξανά με μικρότερα αρχεία ήχου.')}} 
async function storageInfo(){let html='';try{const e=await navigator.storage?.estimate?.();if(e){html='<p class="note">Χρήση χώρου: '+((e.usage||0)/1048576).toFixed(1)+' MB · Διαθέσιμο όριο περίπου '+((e.quota||0)/1048576).toFixed(0)+' MB</p>'}}catch{}return html}
async function settings(){const durable=await navigator.storage?.persist?.().catch(()=>false);const info=await storageInfo();showView('<div class="hero"><div><h2>Ρυθμίσεις & Μεταφορά</h2><p>Σχεδιασμένη για αλλαγή κινητού και υπολογιστή.</p></div><button class="btn light" id="back">← Αρχική</button></div><div class="panel"><h3>🛡️ Προστασία δεδομένων</h3><p>'+(durable?'Το πρόγραμμα περιήγησης ενέκρινε προστατευμένη τοπική αποθήκευση.':'Τα δεδομένα παραμένουν τοπικά. Η προστασία από αυτόματη εκκαθάριση εξαρτάται από τη συσκευή.')+'</p>'+info+'<p class="note">Η εφαρμογή δεν συγχρονίζει αυτόματα μεταξύ συσκευών. Για να μη χαθούν αρχεία, δημιούργησε τακτικά πλήρες αντίγραφο και φύλαξέ το εκτός κινητού.</p><button class="btn gold" id="backupNow">⬇ Δημιουργία ΠΛΗΡΟΥΣ αντιγράφου (με ήχους)</button></div><div class="panel" style="margin-top:14px"><h3>📥 Επαναφορά σε νέα συσκευή</h3><p>Επίλεξε το πλήρες αρχείο JSON που δημιούργησες από την παλιά συσκευή. Η επαναφορά αντικαθιστά τα δεδομένα της εφαρμογής στη νέα συσκευή.</p><div class="field"><label>Αρχείο αντιγράφου ασφαλείας</label><input id="restoreFile" type="file" accept=".json,application/json"></div><button class="btn" id="restoreNow">Επαναφορά δεδομένων</button></div><div class="panel" style="margin-top:14px"><h3>🔌 Μεταφορά μέσω USB</h3><ol><li>Σύνδεσε το παλιό κινητό στον υπολογιστή με USB.</li><li>Επίλεξε «Μεταφορά αρχείων» στο κινητό.</li><li>Αντέγραψε το αρχείο πλήρους αντιγράφου σε φάκελο του υπολογιστή.</li><li>Σύνδεσε το νέο κινητό και αντέγραψε εκεί το ίδιο αρχείο.</li><li>Άνοιξε τη νέα εφαρμογή και επίλεξε «Επαναφορά δεδομένων».</li></ol><p class="note">Κράτησε επίσης ένα δεύτερο αντίγραφο σε USB flash drive ή εξωτερικό δίσκο. Μην βασιστείς μόνο σε μία συσκευή.</p></div>');$('back').onclick=showHome;$('backupNow').onclick=backup;$('restoreNow').onclick=()=>restore({target:{files:[$('restoreFile').files[0]]}})}
async function restore(e){const f=e.target.files?.[0];if(!f)return;try{if(f.size>1024*1024*1024)throw Error('Το αντίγραφο είναι μεγαλύτερο από 1 GB. Χώρισέ το σε μικρότερα αντίγραφα.');const data=JSON.parse(await f.text());if(data.format!=='nikoleta-learning-center'||!Array.isArray(data.records))throw Error('Μη έγκυρο αρχείο αντιγράφου.');if(!confirm('Θα εισαχθούν '+data.records.length+' εγγραφές. Τα υπάρχοντα δεδομένα σε αυτή τη συσκευή θα αντικατασταθούν. Έχεις κρατήσει αντίγραφο των τωρινών δεδομένων;'))return;const restored=data.records.map(item=>{const z={...item,audio:(item.audio||[]).map(a=>{const q={...a};if(a.blobData){q.blob=dataURLToBlob(a.blobData);delete q.blobData}return q})};if(item.fileBlobData){z.fileBlob=dataURLToBlob(item.fileBlobData);delete z.fileBlobData}return z});await replaceAll(restored);alert('Η επαναφορά ολοκληρώθηκε. Βρέθηκαν '+data.records.length+' εγγραφές.');showHome()}catch(err){alert('Δεν έγινε η επαναφορά: '+err.message)}}
