const sidebar=$('sidebar'),scrim=$('menuScrim'),menuToggle=$('menuToggle'),navToggle=$('navToggle');
function closeMenu(){if(navToggle)navToggle.checked=false;sidebar?.classList.remove('open');scrim?.classList.remove('show');menuToggle?.setAttribute('aria-expanded','false')}
function toggleMenu(){if(navToggle){navToggle.checked=!navToggle.checked;return}if(!sidebar)return;const opened=!sidebar.classList.contains('open');sidebar.classList.toggle('open',opened);scrim?.classList.toggle('show',opened);menuToggle?.setAttribute('aria-expanded',String(opened))}
window.toggleLearningMenu=toggleMenu;
window.openLearningSection=async(key)=>{closeMenu();try{if(key==='home'){showHome();return}if(key==='audio'){await audioDashboard();return}if(key==='settings'){await settings();return}if(!simple[key])throw new Error('Δεν υπάρχει ρύθμιση φακέλου για: '+key);await simpleView(key)}catch(err){console.error('Section load failed ['+key+']:',err);const view=$('view');if(view){view.classList.remove('hidden');view.innerHTML='<div class="panel"><h2>Δεν άνοιξε η ενότητα</h2><p>Παρουσιάστηκε σφάλμα κατά τη φόρτωση.</p><p class="note">'+esc(String(err?.message||err))+'</p><button class="btn gold" id="sectionRetry">Δοκίμασε ξανά</button><button class="btn light" id="sectionHome">Αρχική</button></div>';$('sectionRetry').onclick=()=>window.openLearningSection(key);$('sectionHome').onclick=showHome}}};
document.querySelectorAll('.nav [data-home]').forEach(b=>{b.type='button';b.onclick=e=>{e.preventDefault();window.openLearningSection('home')}});
document.querySelectorAll('.nav [data-open]').forEach(b=>{b.type='button';b.onclick=e=>{e.preventDefault();window.openLearningSection(b.dataset.open)}});
$('newSeminar').onclick=newSeminar;$('backupBtn').onclick=backup;
document.querySelectorAll('[data-open="audio"]').forEach(b=>{b.addEventListener('click',async e=>{e.preventDefault();e.stopImmediatePropagation();closeMenu();try{if(!db)await openDB();await audioDashboard()}catch(err){console.error('Audio Academy open error',err);showView('<div class="panel"><h2>Σεμινάρια & Ηχογραφήσεις</h2><p>Δεν ήταν δυνατή η φόρτωση των φακέλων.</p><p class="note">'+esc(String(err?.message||err))+'</p><button class="btn gold" onclick="window.location.reload()">Επαναφόρτωση</button></div>')}},true)});ensureDB().then(async()=>{try{await navigator.storage?.persist?.()}catch{}renderRecent();$('globalSearch')?.addEventListener('input',e=>runGlobalSearch(e.target.value));if('serviceWorker'in navigator)navigator.serviceWorker.register('./sw.js').catch(()=>{})}).catch(e=>alert('Δεν ήταν δυνατή η τοπική βάση δεδομένων: '+e.message));